import{d as r,C as a,o as g,c as d,a3 as t,E as e,j as s,a as h}from"./chunks/framework.Q4yG9rk_.js";const m=JSON.parse('{"title":"正易心法·第四十章","description":"《正易心法》第四十章——名易之义，非训变易：《易》者大易，「未见气」，希微玄虚凝寂；易变而为一，清轻为天、重浊为地、冲和为人；学者作「变易」之解是字言之，非宗旨之学。","frontmatter":{"title":"正易心法·第四十章","description":"《正易心法》第四十章——名易之义，非训变易：《易》者大易，「未见气」，希微玄虚凝寂；易变而为一，清轻为天、重浊为地、冲和为人；学者作「变易」之解是字言之，非宗旨之学。","category":"guide","aliases":["正易心法第四十章","名易之义非训变易","大易与变易"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-40.md","filePath":"yijing/zheng-yi-xin-fa/chapter-40.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-40.md"},x=r({...c,setup(u){const i=[{id:"z40-01",label:"一、非训变易",showLabel:!0,sentences:[["名易之义，非训",{text:"变易",glossary:"bianyi"},"。阴阳根本，有在于是。"]],note:["「易」这个名字的含义，不是训为「变易」。阴阳的根本，就在这里。（**这是《正易心法》中最重要的理论章之一**：前面讲象、讲数、讲筮，**本章追问的是最根本的一问——「易」到底是什么？** 如果连「易」是什么都没搞清楚，所有的象数推演都是空中楼阁。）"]},{id:"z40-02",label:"二、大易未见气",showLabel:!0,sentences:[["《易》者，",{text:"大易",glossary:"dayi"},"也。大易，",{text:"未见气",glossary:"weijianqi"},"也。视之不见，听之不闻，循之不得，故曰《易》。《易》者，",{text:"希微玄虚凝寂",glossary:"xiweiXuanxu"},"之称也。"]],note:["《易》是「大易」；大易，是气尚未出现的状态。看它看不见，听它听不见，摸它摸不着，所以叫做《易》。《易》，是希、微、玄、虚、凝、寂这些词的总称。（**「未见气」三个字要读准**：不是「没有气」，是**「气这个概念都还没有」**——**比「无极」更早，是「无」之前的「无」。** 而「视之不见、听之不闻、循之不得」三句，**几乎直接取自《老子》十四章**（「视之不见名曰夷，听之不闻名曰希，搏之不得名曰微」）——**麻衣只是把「夷希微」换成了「大易」。**）"]},{id:"z40-03",label:"三、易变而为一",showLabel:!0,sentences:[["及易变而为一，一变而为七，七变而为九，九复变而为一也。一者，",{text:"形变之始",glossary:"xingbianZhishi"},"也。清轻者上为天，重浊者下为地，",{text:"冲和气",glossary:"chongheqi"},"者中为人。"]],note:["等到易变化而产生一，一变而到达七，七变而到达九，九再变化回到一。一，是有形变化的起点。清轻之气上升为天，重浊之气下沉为地，冲和之气居中为人。（**三才的生成**：**天与地是气的两个极端**（清轻／重浊），**人是「冲和」的中间状态**——**既不像天那样纯阳，也不像地那样纯阴。** 这正是《老子》「冲气以为和」的落处：**人不是天地的产物，而是与天地同源的第三种气。**）"]},{id:"z40-04",label:"四、本于冲虚",showLabel:!0,sentences:[["谓之《易》者，知阴阳之根本有在于是也。此说本于《",{text:"冲虚真经",glossary:"chongxuZhenjing"},"》，是为定论。"]],note:["之所以称之为《易》，是因为知道阴阳的根本就在这里。这个说法本于《冲虚真经》（《列子》），是定论。（**麻衣的判断很坚决：「是为定论」**——他把《列子》的宇宙论当作**权威依据**。**一个为《易》作注的人，用道家的书来定《易》之名**——这本身就是陈抟一脉「以道解易」的明证。）"]},{id:"z40-05",label:"五、学者盲然不悟",showLabel:!0,sentences:[["学者盲然不悟，乃作变易之易，即是字言之，非",{text:"宗旨之学",glossary:"zongzhiZhixue"},"也。"]],note:["学者茫然不能领悟，把《易》训为「变易」之易——这只是从字面上说，不是把握宗旨的学问。（**麻衣的批评很尖锐**：**如果易＝变化，那《易》就是一本「关于变化的书」，一个用来分析变化的工具。** 但**「变易」说的是「易在变化之中」（工具），麻衣说的是「易在变化之前」（根源）**——**就像水流与水源：研究水流是「变易之学」，追问水源是「大易之学」。**）"]},{id:"z40-06",label:"六、扬雄与日月",showLabel:!0,sentences:[["唯",{text:"扬雄",glossary:"yangxiong"},"为书，拟之曰：《",{text:"太玄",glossary:"taixuan"},"》，颇得之。道家亦以",{text:"日月为易",glossary:"riyueWeiyi"},"，盖其本阴阳而言也。"]],note:["只有扬雄著书，仿《易》命名为《太玄》，颇为得到了真义；道家也用日月来解释「易」字的古字形，这是从阴阳的根本来说的。（**为什么扬雄「颇得之」？** 因为他不把「易」训为「变易」，而直接命名为「**太玄**」——**太＝大，玄＝深远不可见**，与麻衣说的「大易」高度吻合。**但麻衣用「颇」字：得了方向，未全得其本**（《太玄》毕竟是仿作）。**「日月为易」则是「得其象」**：日月已是分化之后的阴阳，而大易是阴阳**之前**——**容器 vs 根源，这是本章最要紧的分辨。**）"]}],p=[{id:"bianyi",term:"变易",pinyin:"biàn yì",meaning:"把「易」训为「变化」。麻衣判为「字言之」，非宗旨之学。"},{id:"dayi",term:"大易",pinyin:"dà yì",meaning:"最根本的易。「未见气」之前的状态，比太极更早。"},{id:"weijianqi",term:"未见气",pinyin:"wèi jiàn qì",meaning:"气尚未出现。比「无极」更彻底的「无」。"},{id:"xiweiXuanxu",term:"希微玄虚凝寂",pinyin:"xī wēi xuán xū",meaning:"五个形容词叠加：希（稀少）、微（细小）、玄（深远）、虚（空无）、凝寂（凝固寂静）。"},{id:"xingbianZhishi",term:"形变之始",pinyin:"xíng biàn zhī shǐ",meaning:"有形变化的起点。一是从无形到有形的第一步。"},{id:"chongheqi",term:"冲和气",pinyin:"chōng hé qì",meaning:"冲和之气。冲＝冲虚，和＝和谐。不轻不重的中间之气，即人的本原。"},{id:"chongxuZhenjing",term:"冲虚真经",pinyin:"chōng xū zhēn jīng",meaning:"《列子》的道教尊称。麻衣以之为「定论」的依据。"},{id:"zongzhiZhixue",term:"宗旨之学",pinyin:"zōng zhǐ zhī xué",meaning:"把握根本宗旨的学问。麻衣认为这才是真正的易学。"},{id:"yangxiong",term:"扬雄",pinyin:"yáng xióng",meaning:"西汉文学家、哲学家（前 53—18），著《太玄经》，仿《易》而作。"},{id:"taixuan",term:"太玄",pinyin:"tài xuán",meaning:"扬雄所著。太＝大，玄＝黑暗深远不可见——与麻衣说的「大易」高度吻合。"},{id:"riyueWeiyi",term:"日月为易",pinyin:"rì yuè wéi yì",meaning:"道家的字形解说：易＝日（阳）＋月（阴）。麻衣评为「本阴阳而言」，方向对但只得其象。"}];return(b,n)=>{const o=a("DaoTextReading"),l=a("DaoKeywordCards");return g(),d("div",null,[n[0]||(n[0]=t(`<h1 id="正易心法·第四十章" tabindex="-1">正易心法·第四十章 <a class="header-anchor" href="#正易心法·第四十章" aria-label="Permalink to &quot;正易心法·第四十章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章是全书最重要的<strong>理论章之一</strong>，直接回答根本问题：<strong>「易」是什么？</strong></p><p><strong>三种解读及其判断</strong>：</p><table tabindex="0"><thead><tr><th>解读</th><th>内容</th><th>依据</th><th>麻衣判断</th></tr></thead><tbody><tr><td><strong>变易</strong></td><td>易＝变化</td><td>《易纬·乾凿度》「易简、变易、不易」</td><td>✗ 只是字面解读，未入根本</td></tr><tr><td><strong>日月</strong></td><td>易＝日＋月</td><td>字形分析（阳＋阴）</td><td>⚠ 方向对，「本阴阳而言」</td></tr><tr><td><strong>大易</strong></td><td>易＝气未见之前的状态</td><td>《列子·天瑞》</td><td>✓✓ 「是为定论」</td></tr></tbody></table><p><strong>三种解读的层次</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>变易（字面）→ 日月（字形）→ 大易（宗旨）</span></span>
<span class="line"><span>= 从表到里，层层深入</span></span>
<span class="line"><span>= 麻衣认为只有第三层才是根本</span></span></code></pre></div><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>「大易」的宇宙生成序列</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>大易（未见气）＝ 希微玄虚凝寂</span></span>
<span class="line"><span>  视之不见，听之不闻，循之不得</span></span>
<span class="line"><span>  = 连「无」都还没有，是「无」之前的状态</span></span>
<span class="line"><span>       ↓ 易变</span></span>
<span class="line"><span>一（形变之始）＝ 气开始出现，但尚未分化</span></span>
<span class="line"><span>       ↓ 一变／七变</span></span>
<span class="line"><span>九（究／极）＝ 气的分化到达极点</span></span>
<span class="line"><span>  清轻者→天，重浊者→地，冲和气→人</span></span>
<span class="line"><span>       ↓ 九复变</span></span>
<span class="line"><span>一（返本）＝ 三才既立，循环重新开始</span></span></code></pre></div><p><strong>对应《老子》的生成论</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>道（大易）→ 一 → 二（天地）→ 三（天地人）→ 万物</span></span>
<span class="line"><span></span></span>
<span class="line"><span>大易 = 道（「视之不见、听之不闻、搏之不得」）</span></span>
<span class="line"><span>一   = 道生一</span></span>
<span class="line"><span>天地 = 一生二</span></span>
<span class="line"><span>人   = 二生三</span></span>
<span class="line"><span>万物 = 三生万物</span></span></code></pre></div><p><strong>麻衣把《列子》和《老子》融合进了易学的宇宙论。</strong></p><p><strong>三才的生成——清轻、重浊、冲和</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>天和地是气的两个极端（分化的结果），人是气的中间状态（未完全分化）</span></span>
<span class="line"><span>= 人不是天地的产物，而是与天地同源的第三种气</span></span>
<span class="line"><span>= 人 = 冲气 = 阴阳相冲而和合的产物</span></span></code></pre></div><p><strong>为什么扬雄「颇得之」？</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>扬雄不把「易」训为「变易」，而是直接命名为「太玄」</span></span>
<span class="line"><span>= 他知道《易》的根本是「玄虚不可见」，不是「变化」</span></span>
<span class="line"><span>「太玄」= 最根本的、不可见的那个东西</span></span>
<span class="line"><span>= 与麻衣说的「大易」（希微玄虚）高度吻合</span></span>
<span class="line"><span></span></span>
<span class="line"><span>但麻衣说「颇得」而非「全得」：</span></span>
<span class="line"><span>  得到了「玄虚」的方向，但《太玄》毕竟是仿作，不是《易》本身的宗旨</span></span></code></pre></div><p><strong>「日月为易」的评价</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>日月（阴阳）= 已经分化之后的状态</span></span>
<span class="line"><span>大易 = 阴阳尚未分化之前的状态</span></span>
<span class="line"><span></span></span>
<span class="line"><span>日月解易：易「包含」阴阳 = 易是阴阳的容器</span></span>
<span class="line"><span>大易解易：易「先于」阴阳 = 易是阴阳的根源</span></span>
<span class="line"><span></span></span>
<span class="line"><span>麻衣的评价：日月解易得其象，大易解易得其本</span></span>
<span class="line"><span>= 所以标题句说「阴阳根本，有在于是」</span></span></code></pre></div><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先把三种解读的层次理清：<strong>变易 → 日月 → 大易</strong>；</li><li>再看「视之不见，听之不闻，循之不得」——<strong>这三句出自《老子》十四章</strong>；</li><li>最后读「非宗旨之学」——<strong>这是麻衣对主流解读的判定。</strong></li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>非训变易</strong>：易不是「变化」。</li><li><strong>大易未见气</strong>：气之前的状态。</li><li><strong>希微玄虚凝寂</strong>：大易的六个特征。</li><li><strong>一者形变之始</strong>：从无到有的第一步。</li><li><strong>三才的生成</strong>：清轻为天、重浊为地、冲和为人。</li><li><strong>本于冲虚</strong>：麻衣以《列子》为定论。</li><li><strong>扬雄颇得之</strong>：太玄得其方向。</li><li><strong>日月为易</strong>：得其象，未得其本。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,24)),e(o,{colophon:"非训变易 · 大易未见气 · 一者形变之始 · 宗旨之学",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第四十章原文",sections:i,glossary:p}),n[1]||(n[1]=s("blockquote",null,[s("p",null,"注：本页依所据底本录入。原文「所之不闻」当为「听之不闻」之讹，此处随底本录入、以上文说明，不作径改。")],-1)),n[2]||(n[2]=s("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),s("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(l,{items:[{term:"大易",pinyin:["dà","yì"],meaning:"《易》的根本含义：气尚未出现之前的状态——比太极更早，是「无」之前的「无」。"},{term:"希微玄虚凝寂",pinyin:["xī","wēi"],meaning:"大易的六个特征：希、微、玄、虚、凝寂——皆不可见不可闻之貌。"},{term:"非训变易",pinyin:["biàn","yì"],meaning:"「易」不是「变化」之意。变易说的是「易在变化之中」，麻衣说的是「易在变化之前」。"},{term:"一者形变之始",pinyin:["xíng","biàn"],meaning:"一是从无形到有形的第一步。清轻为天、重浊为地、冲和为人，三才由此而立。"},{term:"日月为易",pinyin:["rì","yuè"],meaning:"道家字形说：易＝日＋月。麻衣评为「本阴阳而言」——得其象，未得其本。"}]}),n[3]||(n[3]=t(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章回答根本一问：<strong>「易」是什么？</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>三种解读：变易（字面）→ 日月（字形）→ 大易（宗旨）</span></span>
<span class="line"><span>麻衣判：变易 = 字言之；日月 = 得其象；大易 = 定论</span></span></code></pre></div><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>「视之不见，听之不闻，循之不得」——这不就是《老子》吗？</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>《老子》十四章：「视之不见名曰夷，听之不闻名曰希，搏之不得名曰微」</span></span>
<span class="line"><span>麻衣几乎直接引用，但把「夷希微」换成了「大易」</span></span>
<span class="line"><span></span></span>
<span class="line"><span>= 麻衣在说：《老子》的「道」＝《列子》的「大易」＝《周易》的「易」</span></span>
<span class="line"><span>  三个系统的最高概念，指向同一个东西（或同一种不可言说）</span></span></code></pre></div><p><strong>「变易」为什么是错的？</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>如果易＝变化，那《易》就是一本「关于变化的书」，一个用来分析变化的工具</span></span>
<span class="line"><span>但麻衣说：《易》不是关于变化的书，是变化之前的那个东西</span></span>
<span class="line"><span></span></span>
<span class="line"><span>变易之易：易在变化之中（工具）</span></span>
<span class="line"><span>大易之易：易在变化之前（根源）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>就像：水流（变化）vs 水源（根源）</span></span></code></pre></div><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>分清三种解读的层次：<strong>变易 → 日月 → 大易</strong>；</li><li>记住「大易」的性质：<strong>不是「无」，是「无之前的无」</strong>；</li><li>顺着钩子想（承接昇哥的问题）：<strong>用文字描述「不可言说的大易」，本身不就是悖论吗？</strong> 我的看法：<strong>是的，而且麻衣知道这个悖论。</strong> 「希微玄虚凝寂」这六个词，<strong>每一个都是一道「形埒」（边界），把无边界的「大易」框进了有边界的语言。</strong> 但他没有别的工具——<strong>他能做的只是：用足够多的、彼此不完全重叠的词，指向同一个不能说的地方。</strong> 这就像用手指月：<strong>手指不能代替月亮，但没有手指，你连月亮在哪都不知道。</strong> 而<strong>全书最后一章（第四十二章）以「呜乎」收尾，正是他对这个困境的叹息</strong>——<strong>他知道自己也在做「以指指月」的事。</strong> 所以我更愿意把「大易」看作一个<strong>方向</strong>，而不是一个<strong>定义</strong>。</li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>「易」这个名字的含义，不是训为「变易」。阴阳的根本，就在这里。</p><p>《易》，是「大易」；大易，是气尚未出现的状态。看它看不见，听它听不见，摸它摸不着，所以叫做《易》。《易》，是希、微、玄、虚、凝、寂这些词的总称。</p><p>等到易变化而产生一，一变而到达七，七变而到达九，九再变化回到一。一，是有形变化的起点。清轻之气上升为天，重浊之气下沉为地，冲和之气居中为人。</p><p>之所以称之为《易》，是因为知道阴阳的根本就在这里。这个说法本于《冲虚真经》，是定论。</p><p>学者茫然不能领悟，把《易》训为「变易」之易——这只是从字面上说，不是把握宗旨的学问。</p><p>只有扬雄著书，仿《易》命名为《太玄》，颇为得到了真义。道家也用日月来解释「易」字的古字形，这是从阴阳的根本来说的。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第四十章把「易」从「变化」翻过来，还原成「变化之前」——<strong>易不是那本书在讲的道理，是那本书想指的那个东西。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>「非训变易」</strong>——这一刀很关键。<strong>变易说「易在变化之中」，麻衣说「易在变化之前」。</strong> 一个说的是<strong>工具</strong>，一个说的是<strong>根源</strong>。</li><li><strong>「视之不见，听之不闻，循之不得」</strong>——这三句几乎是从《老子》搬来的。<strong>麻衣没有改动，只是把「夷希微」换成了「大易」。</strong> 他在说：<strong>这是同一个东西的不同名字。</strong></li><li><strong>「希微玄虚凝寂」</strong>——六个词叠加，<strong>每一个都在说「不可说」。</strong> 这种堆叠本身就是一种语言的挣扎：<strong>当一个词说不尽，就用一串词来逼近。</strong></li><li><strong>「冲和气者中为人」</strong>——<strong>我很喜欢这一句</strong>：人不是天地的产物，是<strong>第三种气</strong>。清轻为天、重浊为地、<strong>冲和为人</strong>。<strong>人在中间，不是因为「低」，而是因为「和」。</strong></li><li><strong>「扬雄颇得之」</strong>——麻衣给了一个难得的正面评价，但用了「颇」字。<strong>得到方向，没有全得。</strong> 这个分寸很好：<strong>肯定，但不捧杀。</strong></li><li><strong>留给自己的问题</strong>（承接昇哥的钩子）：<strong>用文字描述「不可言说的大易」，本身不就是悖论吗？</strong> 我的看法：<strong>是的，而且麻衣知道。</strong> 「希微玄虚凝寂」<strong>每一词都是一道「形埒」，把无边界的「大易」框进了有边界的语言。</strong> 但他没别的工具。<strong>他能做的，是用足够多、彼此不完全重叠的词，指向同一个不能说的地方。</strong> 就像<strong>用手指月：手指不能代替月亮，但没有手指，你不知道月亮在哪。</strong> 而<strong>全书以「呜乎」收尾，正是他对这个困境的叹息</strong>——<strong>他知道自己也在做「以指指月」的事。</strong> 所以我更愿意把「大易」看作一个<strong>方向</strong>，不是<strong>定义</strong>。</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-21">第二十一章 · 乾坤杂气</a> — 「阴阳一气」（本章「阴阳之根本」的根底）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-39">第三十九章 · 七变归魂</a> — 「一变为七」（本章与之同出《列子》）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-41">第四十一章 · 九流可入</a> — 活法与自悟（本章的方法论对应）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-42">第四十二章 · 舛讹为多</a> — 「呜乎」（全书收尾）</li><li><a href="/Dao/yijing/shi-yi/xi-ci-zhuan-shang">系辞上传</a> — 「易有太极，是生两仪」：本章则问太极之前</li></ul>`,24))])}}});export{m as __pageData,x as default};
